// generated by eider
export interface EiderExports {
  readonly memory: WebAssembly.Memory;
  mean(a: number, b: number): number;
  scale32(x: number, k: number): number;
  is_nan(x: number): boolean;
  trunc_to(x: number): number;
  widen(x: number): number;
  via_host(x: number, y: number): number;
  maths(x: number): number;
  bits(x: number): bigint;
  text(x: number): string;
}
export interface EiderImports { [name: string]: (...args: any[]) => any }
export function load(wasm: BufferSource | WebAssembly.Module, imports?: EiderImports): Promise<EiderExports>;
